import assert from "node:assert/strict";
import { test } from "node:test";
import { decide } from "../screens/access.js";
import { page } from "../pages/fee-waiver-form.js";

test("fee-waiver-form is refused to someone signed in without fees.request", () => {
  assert.equal(decide(page.permission, { signedIn: true, permissions: [] }), "refused");
});

test("fee-waiver-form sends someone signed out to sign in", () => {
  assert.equal(decide(page.permission, { signedIn: false, permissions: [] }), "sign-in");
});

test("fee-waiver-form opens to someone who holds fees.request", () => {
  assert.equal(decide(page.permission, { signedIn: true, permissions: ["fees.request"] }), "allowed");
});
